import time
from Pytrich.Heuristics.heuristic import Heuristic
from Pytrich.Search.htn_node import HTNNode
from Pytrich.model import Model

# This was generated by LLM following the specification and examples
class BlocksworldGemini20FlashHeuristic30(Heuristic):
    def __init__(self, blocksworld_gemini20flash_heuristic_30="blocksworld_gemini20flash_heuristic_30", ontable_penalty=0.1, on_penalty=0.2, clear_penalty=0.05):
        super().__init__(name=blocksworld_gemini20flash_heuristic_30)
        self.ontable_penalty = ontable_penalty
        self.on_penalty = on_penalty
        self.clear_penalty = clear_penalty
        self.method_scores = {}
        self.preprocessing_time = 0

    def initialize(self, model, initial_node):
        """
        Initialize the heuristic with the model and precompute method characteristics.
        """
        start_time = time.time()
        self.model = model
        self._precompute_method_info()
        self.preprocessing_time = time.time() - start_time

        # Calculate initial heuristic value
        h_value = self._calculate_node_heuristic(initial_node)

        return super().initialize(model, h_value)

    def _precompute_method_info(self):
        """
        Precompute information about methods for faster scoring.
        """

        if not self.model:
            return

        # Try different possible attributes for methods
        methods = []

        if hasattr(self.model, 'methods'):
            methods = self.model.methods
        elif hasattr(self.model, 'decompositions'):
            methods = self.model.decompositions
        elif hasattr(self.model, 'tasks'):
            # Get methods from abstract tasks
            for task in self.model.tasks:
                if hasattr(task, 'decompositions'):
                    methods.extend(task.decompositions)

        if not methods:
            return

        for method in methods:
            method_name = method.name if hasattr(method, 'name') else str(method)

            # Count different types of subtasks
            put_on_count = 0
            subtask_count = 0

            # Try different possible attributes for subtasks
            subtasks = []
            if hasattr(method, 'subtasks'):
                subtasks = method.subtasks
            elif hasattr(method, 'task_network'):
                subtasks = method.task_network
            elif hasattr(method, 'decomposition'):
                subtasks = method.decomposition

            if subtasks:
                subtask_count = len(subtasks)
                for subtask in subtasks:
                    subtask_name = ""
                    if hasattr(subtask, 'name'):
                        subtask_name = subtask.name
                    elif hasattr(subtask, 'task'):
                        subtask_name = str(subtask.task)
                    else:
                        subtask_name = str(subtask)

                    subtask_lower = subtask_name.lower()

                    if 'put_on' in subtask_lower or 'do_put_on' in subtask_lower:
                        put_on_count += 1

            self.method_scores[method_name] = {
                'put_on_count': put_on_count,
                'subtask_count': subtask_count,
                'is_put_on_method': self._is_put_on_method(method_name),
                'complexity_score': put_on_count
            }

    def _is_put_on_method(self, method_name):
        """Check if method is for putting one block on another."""
        return 'put_on' in method_name.lower() or 'do_put_on' in method_name.lower()

    def _calculate_node_heuristic(self, node):
        """
        Calculate heuristic value for a node based on its state and the goal conditions.
        """
        if not hasattr(node, 'state'):
            return 0

        state = node.state
        goal = self.model.goals

        h_value = 0

        # Penalize blocks not on the table when they should be
        for goal_fact_id in goal:
            goal_fact = self.model.get_component(goal_fact_id)
            goal_fact_name = goal_fact.name

            if 'ontable' in goal_fact_name:
                if goal_fact_id not in state:
                     h_value += self.ontable_penalty
            elif 'on' in goal_fact_name:
                 if goal_fact_id not in state:
                    h_value += self.on_penalty

        # Reward blocks that are clear when they should be
        for fact_id in range(self.model.ifacts_init, self.model.ifacts_end + 1):
             fact = self.model.get_component(fact_id)
             fact_name = fact.name
             if 'clear' in fact_name and fact_id in state:
                 h_value -= self.clear_penalty

        if hasattr(node, 'method') and node.method:
           h_value += self._score_method(node.method, node) # add method score to heuristic

        return h_value

    def _score_method(self, method, node):
        """
        Score a method based on various factors.
        Lower scores indicate more promising methods (cost-based heuristic).
        """
        score = 0  # Start with 0 cost

        method_name = method.name if hasattr(method, 'name') else str(method)
        method_lower = method_name.lower()

        # Use precomputed info if available
        if method_name in self.method_scores:
            info = self.method_scores[method_name]

            # Small penalties for complexity
            score += info['put_on_count'] * 0.1
            score += info['subtask_count'] * 0.05

        # Method-specific scoring based on name patterns
        if 'put_on' in method_lower or 'do_put_on' in method_lower:
            score -= 0.2  # Reward PutOn operations

        return score

    def __call__(self, parent_node, node):
        """
        Calculate heuristic value for the given node.
        """
        h_value = self._calculate_node_heuristic(node)
        super().update_info(h_value)
        return h_value

    def __repr__(self):
        return f"BlocksworldGemini20FlashHeuristic30(ontable_penalty={self.ontable_penalty}, on_penalty={self.on_penalty}, clear_penalty={self.clear_penalty})"

    def __str__(self):
        return f"BlocksworldGemini20FlashHeuristic30(ontable_penalty={self.ontable_penalty}, on_penalty={self.on_penalty}, clear_penalty={self.clear_penalty})"

    def __output__(self):
        return (
            f"Blocksworld Gemini 2.0 Flash Heuristic 30 info:\n"
            f"\tName: {self.name}\n"
            f"\tMethods analyzed: {len(self.method_scores)}\n"
            f"\tOntable penalty: {self.ontable_penalty}\n"
            f"\tOn penalty: {self.on_penalty}\n"
            f"\tClear penalty: {self.clear_penalty}\n"
            f"\tPreprocessing time: {self.preprocessing_time:.2f} s\n"
        )
